// One result, in the order a non-quant reads it: the headline sentence (generated by the service from the
// numbers), every caveat (warnings in amber, none behind a click), 这个方法 vs 一直持有 vs the index (each may
// be 不可用 with its reason) with the net-value chart and the drawdown under it, the price with the buy and
// sell points, the key figures, the monthly returns, the trades, what was assumed, export, AI 解读.
import { useState, type ReactNode } from 'react'
import { ChevronDown, ChevronRight, Download } from 'lucide-react'
import { Badge, InlineAlert, Stat, StatGroup, buttonClass, cx, focusRing, numeric } from '@/components/ui'
import { pnlTextClass } from '@/lib/pnlColor'
import {
  allMetrics, caveatTone, comparisons, endMarkOf, keyFigures, legacyView, orderedCaveats, type Comparison,
} from '@/features/backtest/result'
import { exportUrl, type RunSnapshot, type RunResult } from '@/services/backtest'
import { Assumptions } from './Assumptions'
import { EquityChart } from './EquityChart'
import { MonthlyReturns } from './MonthlyReturns'
import { PriceChart } from './PriceChart'
import { Reflection } from './Reflection'
import { RerunPanel } from './RerunPanel'
import { FillsTable, RoundTripsTable, UnfilledTable } from './ResultTables'
import type { ReflectionView } from './hooks'

function ComparisonItem({ item }: { item: Comparison }) {
  return (
    <div className="min-w-0" data-comparison={item.key}>
      <dt className="text-table text-fg-2">{item.label}</dt>
      <dd>
        {item.value === null ? (
          <>
            <span className="text-title font-normal text-fg-3">不可用</span>
            <p className="mt-0.5 text-table text-fg-3">{item.reason}</p>
          </>
        ) : (
          <span className={cx('text-title', numeric, pnlTextClass(item.tone))}>{item.value}</span>
        )}
      </dd>
    </div>
  )
}

function Section({ title, children, label }: { title?: string; label?: string; children: ReactNode }) {
  return (
    <section aria-label={label ?? title} className="flex min-w-0 flex-col gap-3 border-t border-line pt-5">
      {title && <h3 className="text-title text-fg">{title}</h3>}
      {children}
    </section>
  )
}

function MoreMetrics({ result }: { result: RunResult }) {
  const [open, setOpen] = useState(false)
  const metrics = allMetrics(result)
  const Icon = open ? ChevronDown : ChevronRight
  return (
    <div className="flex min-w-0 flex-col gap-3">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen(!open)}
        className={cx('inline-flex w-fit items-center gap-1 rounded-sm text-body font-medium text-fg-2 hover:text-fg', focusRing)}
      >
        <Icon size={16} aria-hidden />
        更多指标（{metrics.length}）
      </button>
      {open && (
        <dl className="grid min-w-0 gap-x-8 gap-y-3 md:grid-cols-2">
          {metrics.map((metric) => (
            <div key={metric.key} className="min-w-0">
              <dt className="flex flex-wrap items-baseline justify-between gap-x-3">
                <span className="text-body text-fg-2">{metric.label}</span>
                {metric.value === null ? (
                  <span className="text-body text-fg-3">不可用</span>
                ) : (
                  <span className={cx('text-body', numeric, metric.tone === 'flat' ? 'text-fg' : pnlTextClass(metric.tone))}>{metric.value}</span>
                )}
              </dt>
              <dd className="text-table text-fg-3">
                {metric.value === null && metric.reason ? `${metric.reason}。` : ''}
                {metric.note}
              </dd>
            </div>
          ))}
        </dl>
      )}
    </div>
  )
}

export interface ResultViewProps {
  snapshot: RunSnapshot
  result: RunResult
  reflection: { view: ReflectionView; starting: boolean; start: () => void }
}

export function ResultView({ snapshot, result, reflection }: ResultViewProps) {
  const facts = result.facts
  const caveats = orderedCaveats(result.caveats)
  const warnings = caveats.filter((item) => item.level === 'warning').length
  const items = comparisons(result)
  const figures = keyFigures(result)
  const endMark = endMarkOf(result)
  // A record saved by an older version: shown with what it has; each part it lacks says 不可用 and why.
  const legacy = legacyView(result)
  const period = facts.period?.first_date && facts.period?.last_date
    ? `${facts.period.first_date} 至 ${facts.period.last_date}${facts.period.span_label ? `（${facts.period.span_label}）` : ''}`
    : null
  return (
    <article aria-label="回测结果" className="flex min-w-0 flex-col gap-5">
      <header className="flex min-w-0 flex-col gap-3">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div className="min-w-0">
            <h2 className="text-title text-fg">
              {facts.name && facts.name !== facts.ticker ? `${facts.name} ` : ''}
              <span className={cx('text-fg-2', numeric)}>{facts.ticker}</span>
              {facts.strategy?.name ? ` · ${facts.strategy.name}` : ''}
            </h2>
            <p className={cx('text-table text-fg-3', numeric)}>
              {[period, facts.market_label, facts.currency].filter(Boolean).join(' · ')}
            </p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {facts.demo && <Badge tone="warn">演示数据，不是真实行情</Badge>}
            {legacy && <Badge tone="warn">旧版本记录（{legacy.savedBy}）</Badge>}
            {snapshot.kind === 'saved' && <Badge>历史记录</Badge>}
            {snapshot.kind === 'rerun' && <Badge>重跑</Badge>}
            {snapshot.kind !== 'saved' && <Badge>{snapshot.saved_to_history ? '已保存到历史' : '没有保存到历史'}</Badge>}
            <a href={exportUrl(snapshot.run_id, 'csv')} download className={buttonClass({ size: 'sm' })}>
              <Download size={14} aria-hidden />导出 CSV
            </a>
            <a href={exportUrl(snapshot.run_id, 'json')} download className={buttonClass({ size: 'sm', variant: 'ghost' })}>
              导出 JSON
            </a>
          </div>
        </div>
        <p className="text-title font-normal leading-7 text-fg">{result.headline_zh}</p>
      </header>

      <RerunPanel result={result} />

      <section aria-label="可信度提醒" className="flex min-w-0 flex-col gap-2">
        <h3 className="text-title text-fg">
          可信度提醒
          <span className={cx('ml-2 text-table font-normal text-fg-3', numeric)}>{caveats.length} 条{warnings ? `，其中 ${warnings} 条需要注意` : ''}</span>
        </h3>
        {caveats.length === 0 && <p className="text-table text-fg-3">这次结果没有附带提醒。</p>}
        <ul className="flex flex-col gap-2">
          {caveats.map((item, index) => (
            <li key={`${item.code}-${index}`} data-caveat={item.code}>
              <InlineAlert tone={caveatTone(item)}>{item.text}</InlineAlert>
            </li>
          ))}
        </ul>
      </section>

      {legacy && (
        <section aria-label="旧版本记录" className="flex min-w-0 flex-col gap-2">
          <h3 className="text-title text-fg">旧版本记录没有的部分</h3>
          <p className="text-table text-fg-3">下面这些在结果里显示为不可用；这条记录不能重跑，导出的文件里同样标明。</p>
          <ul className="flex list-disc flex-col gap-1 pl-5 text-table text-fg-2">
            {legacy.parts.map((part) => <li key={part.key} className="whitespace-normal break-words">{part.label}</li>)}
          </ul>
        </section>
      )}

      <Section title="和什么比">
        <dl className="grid min-w-0 gap-4 sm:grid-cols-3">
          {items.map((item) => <ComparisonItem key={item.key} item={item} />)}
        </dl>
        <p className="text-table text-fg-3">“一直持有”是同一只股票、同样本金和费用、第一天买入拿到最后；指数不扣费用。</p>
        <EquityChart result={result} />
      </Section>

      <Section>
        <PriceChart result={result} />
      </Section>

      <Section title="关键数字">
        <StatGroup>
          {figures.map((figure) => (
            <Stat
              key={figure.key}
              label={figure.label}
              value={figure.value}
              tone={figure.tone}
              unavailableReason={figure.reason ?? undefined}
              sub={figure.sub ? <span className="text-table text-fg-3">{figure.sub}</span> : undefined}
            />
          ))}
        </StatGroup>
        <MoreMetrics result={result} />
      </Section>

      <Section>
        <MonthlyReturns result={result} />
      </Section>

      <Section label="交易">
        <RoundTripsTable trips={result.round_trips ?? []} facts={facts} endMark={endMark} unavailable={legacy?.unavailable('round_trips')} />
        <UnfilledTable entries={result.unfilled ?? []} unavailable={legacy?.unavailable('unfilled')} />
        <FillsTable fills={result.fills ?? []} facts={facts} endMark={endMark} detailUnavailable={legacy?.unavailable('fills_detail')} />
      </Section>

      <Section>
        <Assumptions result={result} />
      </Section>

      <Section>
        <Reflection view={reflection.view} starting={reflection.starting} onStart={reflection.start} />
      </Section>
    </article>
  )
}
